        public static string GetTestSample()
        {
            return GetTestSample(System.Text.Encoding.GetEncoding(28591));
        }

        public static string GetTestSample(System.Text.Encoding encoding)
        {
            byte[] bytes = Combine(GetTestChunks());
            return encoding.GetString(bytes);
        }

        private static byte[] Combine(IReadOnlyList<byte[]> chunks)
        {
            int length = 0;
            for (int index = 0; index < chunks.Count; index++)
                length += chunks[index].Length;

            byte[] bytes = new byte[length];
            int offset = 0;
            for (int index = 0; index < chunks.Count; index++)
            {
                byte[] chunk = chunks[index];
                Buffer.BlockCopy(chunk, 0, bytes, offset, chunk.Length);
                offset += chunk.Length;
            }

            return bytes;
        }

        private static byte[] ParseChunk(string hex)
        {
            string[] parts = hex.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            byte[] bytes = new byte[parts.Length];

            for (int index = 0; index < parts.Length; index++)
                bytes[index] = Convert.ToByte(parts[index], 16);

            return bytes;
        }
    }
